
# Lesson 07: Understanding Embeddings
#
# This is a conceptual demonstration using invented vectors.
# These are NOT real embeddings generated by an AI model.

texts = [
    "How can I reset my password?",
    "How do I recover my forgotten password?",
    "What is the weather today?",
]

# Illustrative vectors created manually for learning purposes.
# Real embedding models generate vectors from text.
illustrative_vectors = [
    [0.90, 0.80, 0.10],
    [0.88, 0.82, 0.12],
    [0.10, 0.15, 0.95],
]

print("Understanding text and vectors")
print("=" * 50)

for text, vector in zip(texts, illustrative_vectors):
    print("Text:", text)
    print("Vector:", vector)
    print("Number of dimensions:", len(vector))
    print("-" * 50)

print()
print("Important:")
print("These numbers are invented examples.")
print("A real embedding model generates vectors from text.")
